package org.diy.liferecorder;
import android.widget.*;import org.json.*;
/** Suggestions are evidence, never deletion authority. Model judgments are tied to the current text. */
final class AudioReview {
 static final String PROMPT="可另输出audio_review对象，字段classification只能为noise_or_unusable、meaningful或uncertain，suggest_delete为布尔值，reason为简短理由。你只收到转写与本地检测统计，没有试听原始音频，不得声称听过录音。仅在转写几乎全为噪声标记、无意义重复且缺乏有效信息时建议删除；短对话、人声少、多人或背景声本身不构成删除理由。无法判断则uncertain且suggest_delete=false。建议不能执行删除。";
 static JSONObject object(String value){try{return new JSONObject(value);}catch(Exception e){return new JSONObject();}}
 static String textHash(String text)throws Exception{return org.diy.lifecore.LocalSecurity.hex(java.security.MessageDigest.getInstance("SHA-256").digest(text.getBytes("UTF-8")));}
 static JSONObject evidence(JSONObject audio)throws Exception{JSONObject speech=object(audio.optString("speech_json")),vad=object(audio.optString("vad_map"));JSONObject out=new JSONObject().put("audio_ms",audio.optLong("duration")).put("original_audio_provided",false);if(speech.has("no_speech_detected"))out.put("no_speech_detected",speech.optBoolean("no_speech_detected"));else if(vad.has("no_speech_detected"))out.put("no_speech_detected",vad.optBoolean("no_speech_detected"));if(speech.has("voiced_ms"))out.put("voiced_ms",speech.optLong("voiced_ms"));return out;}
 static void sealAdvice(JSONObject analysis,String transcript)throws Exception{JSONObject raw=analysis.optJSONObject("audio_review");if(raw==null)return;String kind=raw.optString("classification");if(!kind.equals("noise_or_unusable")&&!kind.equals("meaningful")&&!kind.equals("uncertain")){analysis.remove("audio_review");return;}String reason=raw.optString("reason").trim();if(reason.length()>500)reason=reason.substring(0,500);analysis.put("audio_review",new JSONObject().put("classification",kind).put("suggest_delete",Boolean.TRUE.equals(raw.opt("suggest_delete"))&&kind.equals("noise_or_unusable")&&!reason.isEmpty()).put("reason",reason).put("transcript_sha256",textHash(transcript)).put("basis","transcript-and-local-detection-only"));}
 static String reason(JSONObject audio){try{JSONObject speech=object(audio.optString("speech_json")),vad=object(audio.optString("vad_map"));if(audio.optString("transcript").trim().isEmpty()&&(speech.optBoolean("no_speech_detected")||vad.optBoolean("no_speech_detected")))return "本地检测未发现有效人声，建议先试听，再决定是否删除。";JSONObject review=object(audio.optString("analysis")).optJSONObject("audio_review");if(review!=null&&Boolean.TRUE.equals(review.opt("suggest_delete"))&&review.optString("classification").equals("noise_or_unusable")&&review.optString("transcript_sha256").equals(textHash(audio.optString("transcript"))))return "LLM 根据转写与本地检测统计，认为内容疑似杂音或无有效信息；没有试听原音。"+"\n"+review.optString("reason");}catch(Exception ignored){}return "";}
 static boolean suggested(JSONObject audio){return !reason(audio).isEmpty();}
 static void explain(AppScreen screen,LinearLayout parent,JSONObject audio){String reason=reason(audio);if(reason.startsWith("本地"))parent.addView(screen.text(reason,13,screen.SAGE));else{parent.addView(screen.text("LLM 根据转写与本地检测统计提出建议，未试听原音。",13,screen.SAGE));parent.addView(screen.rawText(object(audio.optString("analysis")).optJSONObject("audio_review").optString("reason"),13,screen.MUTED));}}
 static void show(AppScreen screen,LinearLayout parent,JSONObject audio,Runnable listen,Runnable changed){String reason=reason(audio);if(reason.isEmpty()||audio.optString("path").isEmpty())return;LinearLayout c=screen.card(parent);c.addView(screen.title("这段录音可能可以清理",17));explain(screen,c,audio);c.addView(screen.text("不会自动删除。请先确认没有需要保留的声音、文字或待办。",12,screen.MUTED));screen.button(c,"先试听这段录音",listen);screen.button(c,"核对后删除这段录音",()->AudioActions.show(screen,audio.optString("id"),changed));}
}
